import{_ as t,o as e,c as r,a3 as l}from"./chunks/framework.Dj4Lt7vj.js";const _=JSON.parse('{"title":"套餐与开通","description":"","frontmatter":{"title":"套餐与开通"},"headers":[],"relativePath":"start/plan.md","filePath":"start/plan.md","lastUpdated":1787949005000}'),o={name:"start/plan.md"};function i(d,a,n,s,h,c){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="套餐与开通" tabindex="-1">套餐与开通 <a class="header-anchor" href="#套餐与开通" aria-label="Permalink to &quot;套餐与开通&quot;">​</a></h1><p>熠智 AI 按「套餐 + 点数」计费。这一页讲清套餐的结构；点数怎么扣见<a href="/aicare-docs/billing/points">点数怎么计算</a>。</p><h2 id="套餐结构" tabindex="-1">套餐结构 <a class="header-anchor" href="#套餐结构" aria-label="Permalink to &quot;套餐结构&quot;">​</a></h2><ul><li><strong>订阅套餐</strong>：按月或按年订阅。客服接待点数每 30 天发放一次，周期内没用完不结转。运营助手使用另一份额度，按自然月累计，每月 1 日重置。</li><li><strong>加油包</strong>：一次性购买的客服接待点数包。套餐点数用完后自动消耗加油包点数。部分加油包有有效期，部分永久有效，购买时会注明。加油包不包含运营助手额度。</li><li><strong>兑换码</strong>：销售发放的码，可兑换套餐或点数，见<a href="/aicare-docs/billing/redeem">兑换码</a>。</li></ul><p>具体档位、价格、额度和开放能力可能调整，以客户端「账单」页当前展示和销售报价为准。</p><h2 id="套餐权益差异" tabindex="-1">套餐权益差异 <a class="header-anchor" href="#套餐权益差异" aria-label="Permalink to &quot;套餐权益差异&quot;">​</a></h2><p>不同档位除了点数额度，还会限制部分能力，常见的有：</p><table tabindex="0"><thead><tr><th>权益</th><th>说明</th></tr></thead><tbody><tr><td>客服账号接入位</td><td>每个接入的客服账号占一个接入位，可用数量按套餐开放</td></tr><tr><td>AI 方案数量</td><td>低档位限制方案数量</td></tr><tr><td>情景与触发规则</td><td>按不同客户情景分流回复，见<a href="/aicare-docs/solution/triggers">情景与触发规则</a>，部分档位开放</td></tr><tr><td>商品智能学习</td><td>用大模型整理商品资料，见<a href="/aicare-docs/knowledge/product-learn">商品学习</a>，部分档位开放</td></tr></tbody></table><p>客户端里标注「需开通」的功能，表示当前套餐未包含。想开通请联系销售。</p><h2 id="怎么开通" tabindex="-1">怎么开通 <a class="header-anchor" href="#怎么开通" aria-label="Permalink to &quot;怎么开通&quot;">​</a></h2><p>目前<strong>不支持在线支付</strong>。开通流程是：</p><ol><li>通过客户端菜单里的「联系我们」或官网找到销售。</li><li>确认档位和时长，完成付款。</li><li>销售开通到账号，或发给你兑换码，在「账单」页自助兑换。</li></ol><p>详见<a href="/aicare-docs/billing/purchase">购买套餐和加油包</a>。</p><h2 id="查看当前套餐" tabindex="-1">查看当前套餐 <a class="header-anchor" href="#查看当前套餐" aria-label="Permalink to &quot;查看当前套餐&quot;">​</a></h2><p>打开客户端左侧菜单「账单」，页面顶部显示当前可用点数和套餐额度，消耗记录会列出每类动作实际扣了多少。网页工作台的「账单」标签页内容相同。</p>',15)])])}const u=t(o,[["render",i]]);export{_ as __pageData,u as default};
